[
  {
    "question": "Welcome! To start, I'd love to hear a bit about what initially drew you to software engineering and what kind of technical challenges you find most engaging or rewarding to tackle. What excites you most about building software?",
    "category": "Behavioral/Motivation",
    "difficulty": "easy",
    "expectedTopics": ["Personal motivation", "Problem-solving interests", "Technical curiosity", "Career aspirations"]
  },
  {
    "question": "Could you tell me about a specific project, either from a past role or a personal endeavor, where you encountered a significant technical challenge or a complex problem? Walk me through how you approached understanding the problem, what steps you took to solve it, and what alternatives or trade-offs you considered along the way.",
    "category": "Technical/Problem Solving",
    "difficulty": "medium",
    "expectedTopics": ["Project overview", "Technical challenge identification", "Problem-solving methodology", "Decision-making", "Trade-offs", "Outcomes"]
  },
  {
    "question": "In a fast-paced environment like Big Tech, you'll often encounter unfamiliar codebases or systems. Imagine you're tasked with debugging an unexpected performance degradation in a service that's critical but new to you. How would you typically go about diagnosing the root cause of such an issue, and what's your approach to quickly getting up to speed on a new technical domain or system?",
    "category": "Technical/Troubleshooting/Learning",
    "difficulty": "medium",
    "expectedTopics": ["Debugging strategies", "Root cause analysis", "System understanding", "Learning new technologies", "Resourcefulness", "Collaboration"]
  }
]
